            elif r == 2 or c == 2:
                out[r][c] = 4

    # Find the horizontal repeat length in the undisturbed part of the pattern.
    best_period, best_score = 1, -1
    for p in range(2, 10):
        same = total = 0
        for r in range(3, h):
            for c in range(6, w - p):
                a, b = grid[r][c], grid[r][c + p]
                if a and b:
                    total += 1
                    same += (a == b)
        score = same / total if total else 0
        if score > best_score:
            best_period, best_score = p, score

    # Each row repeats horizontally; use intact cells from the regular
    # portion of that row to restore the masked cells.
    for r in range(3, h):
        for c in range(3, w):
            if grid[r][c] != 0:
                continue
            for k in range(6, w):
                if grid[r][k] != 0 and (k - c) % best_period == 0:
                    out[r][c] = grid[r][k]
                    break

    return out
